function henrion5(; np = AbstractAlgebra, k = np.QQ, internal_ordering = :degrevlex)
    (_, (f1, f2, f3, f4, f5, t)) = np.polynomial_ring(k, ["f1", "f2", "f3", "f4", "f5", "t"], internal_ordering = internal_ordering)
    [2 * f1 * f2 * f3 * f4 * f5 - 9823275, (k(21) // k(5) * f1 * f2 * f4 * f5 + k(16) // k(5) * f1 * f3 * f4 * f5 + k(9) // k(5) * f2 * f3 * f4 * f5 + k(24) // k(5) * f1 * f2 * f3 * f5 + 5 * f4 * f3 * f1 * f2) - 4465125, (k(14) // k(5) * f4 * f5 * f1 + k(14) // k(5) * f4 * f5 * f2 + k(8) // k(5) * f3 * f4 * f5 + k(18) // k(5) * f1 * f2 * f5 + k(24) // k(5) * f1 * f3 * f5 + k(18) // k(5) * f2 * f3 * f5 + 4 * f3 * f1 * f2 + 6 * f1 * f2 * f4 + 6 * f3 * f4 * f1 + 4 * f2 * f3 * f4) - 441486, (k(7) // k(5) * f4 * f5 + k(12) // k(5) * f5 * f1 + k(12) // k(5) * f5 * f2 + k(12) // k(5) * f5 * f3 + 3 * f1 * f2 + 4 * f3 * f1 + 4 * f4 * f1 + 3 * f2 * f3 + 4 * f4 * f2 + 3 * f3 * f4) - 15498, (k(6) // k(5) * f5 + 2 * f4 + 2 * f3 + 2 * f2 + 2 * f1) - 215, f1 + 2 * f2 + 3 * f3 + 4 * f4 + 5 * f5 + 6t]
end
